/**
 * A user-facing error generated by Dock (not Pi/OS). The browser translates
 * `key` with its current language; the raw `message` stays for compatibility.
 */
export class DockError extends Error {
	/** @param {string} key @param {Record<string, unknown>} [params] */
	constructor(key, params = {}) {
		super(key);
		this.name = "DockError";
		this.key = key;
		this.params = params;
	}
}
